/* Local-only demo catalog: built from the existing server-side catalog. */
import { readFileSync, writeFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const { products } = JSON.parse(readFileSync(join(root, 'backend/supabase/functions/ownpay-checkout/catalog.json'), 'utf8'));
const quote = value => `'${String(value).replaceAll("'", "''")}'`;
const categories = new Set(products.map(p => p.cat));
const lines = [
  '-- LOCAL ONLY: generated by node tools/gen-local-seed.mjs from the bundled catalog.',
  '-- One primary size per slug. Other size variants are not yet supported by demo-payment-kit.',
  'INSERT INTO public.categories (slug, name) VALUES',
  [...categories].map(cat => `  (${quote(cat)}, ${quote(cat.split('-').map(word => word[0].toUpperCase() + word.slice(1)).join(' '))})`).join(',\n') + '\nON CONFLICT (slug) DO NOTHING;',
  'INSERT INTO public.products (slug, name, category_slug, unit, price, in_stock) VALUES',
  products.map(p => {
    const size = p.sizes.find(([unit]) => unit === '1 L') || p.sizes[0];
    return `  (${quote(p.slug)}, ${quote(p.name)}, ${quote(p.cat)}, ${quote(size[0])}, ${size[1]}, ${p.stock ? 'true' : 'false'})`;
  }).join(',\n') + '\nON CONFLICT (slug) DO NOTHING;'
];
writeFileSync(join(root, 'backend/supabase/seed.sql'), lines.join('\n\n') + '\n');
console.log(`Local-only catalog seed generated (${products.length} products)`);